/* Full Exam One lab. All activities share the existing Diagnostics course record. */
(function(){
  'use strict';
  const T=window.DX_EXAM1, E=window.DXTopicEngine, Store=window.DXTopicStore;
  const byId=Object.fromEntries(T.items.map(i=>[i.id,i]));
  const mockById=Object.fromEntries((T.mockItems||T.items).map(i=>[i.id,i]));
  const sources=Object.fromEntries(T.evidence.map(e=>[e.id,e]));
  const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const stamp=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');
  const date=t=>new Date(t).toLocaleString([],{dateStyle:'short',timeStyle:'short'});
  const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
  const labels={practice:'Adaptive practice',cases:'Case decisions',test:'Topic Mock A',listing:'Listing practice',review:'Missed concepts'};
  let api=null,root=null,tick=null,correctionOpen=null,reviewOpen=new Set(),chapter=null;
  const chapterById=Object.fromEntries(window.DX_CHAPTERS.map(c=>[c.id,c]));
  const ev=()=>Object.fromEntries(Object.keys(T.concepts).map(c=>[c,{...E.evidence(topic(),[c])[c],...(api.state.concepts[c]||{})}]));
  const bank=()=>T.items.filter(q=>!chapter||q.chapter===chapter.id);
  const labelRun=r=>r.label||labels[r.type]||r.type;
  function topic(){const a=Store.topic(api.state,'exam1'),b=Store.topic(api.state,'cas');return Store.mergeTopics({combined:b},{combined:a}).combined;}
  function derive(s){window.DXSlidePriority.refreshUnanswered(s);return E.deriveCourse(s,Object.keys(T.concepts),T.legacyConceptIds,T.legacyItemIds);}
  function change(fn){api.mutate(s=>{window.DXSlidePriority.refreshUnanswered(s);const a=Store.topic(s,'exam1'),b=Store.topic(s,'cas'),t=Store.mergeTopics({combined:b},{combined:a}).combined;fn(t,s);t.updated=Date.now();s.topics.exam1=t;if(b.activeId&&t.runs[b.activeId]?.status!=='active')b.activeId=null;derive(s);});}
  function go(view){location.hash='#/topic/'+view;}
  function renderNow(){render(api,location.hash.replace(/^#\/?topic\/?/,'').split('/').filter(Boolean));}
  function evidenceHTML(ids){return `<details class="source-box"><summary>Course sources and explanation</summary>${ids.map(k=>{const s=sources[k];return `<section><h3>${esc(s.title)}</h3>${s.summary?'<p class="muted small">Source-linked study explanation; original locators retained below.</p>':''}<pre>${esc(s.text)}</pre>${s.image?`<figure><a href="${s.image}" target="_blank" rel="noopener"><img src="${s.image}" alt="${esc(s.imageTitle||'Original figure included in '+s.title)}" loading="lazy"></a><figcaption>${esc(s.imageTitle||'Supplied course figure, unchanged.')} Open to enlarge; original credit retained.</figcaption></figure>`:''}</section>`;}).join('')}</details>`;}
  function skills(selectedIds){const e=ev(),ids=selectedIds||(chapter?Object.keys(T.concepts).filter(c=>chapter.modules.includes(window.DX_DATA.concepts[c]?.module)):Object.keys(T.concepts));return ids.map(c=>{const v=e[c];return `<div class="skill-row"><span>${esc(T.concepts[c])}</span><span class="skill-state ${v.mastered?'earned':''}">${v.mastered?'Mastered':v.attempts?`Learning · ${v.correct}/${v.attempts} correct`:'Not started'}${v.needsReview?`<span class="review-tag">${v.misconception?'High-confidence miss':'Review due'}</span>`:''}</span></div>`;}).join('');}
  function heading(eye,title,lede){return `<p class="eyebrow">${eye}</p><h1>${title}</h1>${lede?`<p class="lede">${lede}</p>`:''}`;}
  function header(view){if(view==='activity')return heading('October 5 activity · ASHA Module 9','Assessment decisions when testing is limited','Use the decision tree, explain the limitation, and choose the next evidence.');if(view==='home')return heading('Exam one · Monday, October 12','Learn the distinction.<br>Practice the decision.','All nine Exam One chapters. Current Diagnostics evidence, narrated learning, and one saved mastery record. Formatting transcript and instructor study guide expected Wednesday, October 7.');if(view==='guide')return heading('Teach before testing','Study guide','Nine chapters covering Weeks 1–6 and the relevant assigned materials. Exam: October 12. Formatting transcript and instructor study guide expected October 7.');if(view==='learn')return heading(chapter.week,esc(chapter.title),esc(chapter.summary));if(view==='review')return heading('Targeted retrieval','Review what needs attention','Earned mastery stays earned. Later misses still return for repair.');if(view==='sources')return heading('Current course evidence','Sources and exam design','Current slides and lectures govern content. Historical Language Disorders exams guide response format.');if(view==='backup')return heading('Portable progress','Backup and restore','Import merges compatible records without deleting existing work.');if(view==='progress')return heading('Saved across study modes','Your progress','Earlier scores, first answers, corrections, notes and saved versions remain available. <a href="#/progress">Review earlier exam records</a>.');return heading(chapter?chapter.week:'Exam One · cumulative retrieval',view==='test'?'Mock exams':view==='cases'?'Case decisions':view==='practice'?'Practice':'Saved activity',chapter?esc(chapter.title):'All nine chapters');}
  function tabs(view){return chapter?`<nav class="tabs" aria-label="Chapter activities"><a class="btn ${view==='learn'?'active':''}" href="#/topic/learn/${chapter.id}">Study guide</a><a class="btn" href="#/topic/practice/${chapter.id}">Practice chapter</a><a class="btn" href="#/topic/cases/${chapter.id}">Case decisions</a><button class="btn" data-topic="start" data-mode="listing">Listing drill</button><a class="btn" href="#/topic/guide">All chapters</a></nav>`:'';}
  function topicCard(c){const e=ev(),counts=window.DXSlidePriority.completion(e,c.modules),ids=T.completionConceptIds.filter(id=>c.modules.includes(window.DX_DATA.concepts[id]?.module)),n=counts.existing.mastered;return `<article class="card"><p class="eyebrow">${esc(c.week)}</p><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><p class="small">${n} / ${ids.length} concepts mastered</p><div class="progress" aria-label="${n} of ${ids.length} concepts mastered"><i style="width:${ids.length?n/ids.length*100:0}%"></i></div>${counts.added.total?`<p class="small">New material: ${counts.added.mastered} / ${counts.added.total} concepts mastered separately</p>`:''}<div class="row"><a class="btn" href="#/topic/learn/${c.id}">Study guide + film</a><a class="btn" href="#/topic/practice/${c.id}">Practice</a></div></article>`;}
  function resumeHTML(){const r=activeRun();return r?`<section class="card"><div class="row spread"><div><h3>${esc(labelRun(r))}</h3><p class="small">${Object.keys(r.responses).length} checked · saved activity</p></div><a class="btn" href="#/topic/run/${r.id}">Resume</a></div></section>`:'';}
  function home(){const t=topic(),e=ev(),runs=Object.values(t.runs),counts=window.DXSlidePriority.completion(e),n=counts.existing.mastered,review=Object.values(e).filter(v=>v.needsReview).length;return `<div class="stats"><div class="stat"><strong>${n}/${counts.existing.total}</strong><span>Original concepts mastered</span></div><div class="stat"><strong>${Object.values(api.state.items).reduce((n,x)=>n+(x.n||0),0)}</strong><span>Saved checked attempts</span></div><div class="stat"><strong>${review}</strong><span>Concepts due for review</span></div><div class="stat"><strong>9</strong><span>Narrated chapters</span></div></div><p class="small completion-note">Original chapter completion keeps its 103-concept total. New activity and checklist mastery are tracked below.</p>${resumeHTML()}<div class="row"><a class="btn pri" href="#/topic/practice">Start mixed practice</a><a class="btn" href="#/topic/test">Choose a mock</a><a class="btn" href="#/topic/backup">Backup progress</a></div>${window.DXOct5.card(ev())}<h2>Choose a chapter</h2><div class="grid">${window.DX_CHAPTERS.map(topicCard).join('')}</div><p class="small">Mastery is earned through distinct questions with confidence. Two consecutive correct, unhinted answers on different questions earn mastery when the latest confidence is medium or high. A wrong answer resets the qualifying streak and adds review. Earned mastery stays earned. Reading, corrections and self-scored listings do not award automated mastery.</p><details class="source-box"><summary>Earlier activities and numerical tools</summary><p><a href="#/home">Open the original lab and saved older exams</a> · <a href="#/tools">Numerical tools</a>. The new chapter structure shares the existing course record.</p></details>`;}
  function guide(){return `${window.DXOct5.card(ev())}<div class="grid">${window.DX_CHAPTERS.map(topicCard).join('')}</div>`;}
  function review(){const e=ev(),due=Object.entries(e).filter(([c,v])=>v.needsReview);return `${resumeHTML()}${due.length?'<button class="btn pri" data-topic="start" data-mode="review">Start targeted review</button>':'<section class="card"><h2>No review questions due.</h2><p>Check some practice questions to build your review queue.</p><a class="btn" href="#/topic/practice">Start practice</a></section>'}${due.map(([c,v])=>`<section class="card"><h3>${esc(T.concepts[c])}</h3><p>${v.misconception?'High-confidence miss': 'Review due'}${v.mastered?' · mastery retained':''}</p><button class="btn" data-topic="start" data-mode="practice" data-concept="${c}">Practice this concept</button></section>`).join('')}`;}
  function sourcePage(){return `<section class="card"><h2>Exam One coverage</h2><p><strong>Slides and current lectures set the main content.</strong> Assigned videos reinforce their main ideas; mastery practice gives the necessary scenario facts rather than testing video case recall or incidental statistics.</p><p><a href="#/topic/activity/oct5">October 5 assigned activity:</a> diagnostic decision tree and assessment limitations from <a href="https://tlr-hub.asha.org/learning-modules/implementation-and-evaluation-of-the-decision/" target="_blank" rel="noopener">ASHA Module 9</a>. Confirmed Exam 1 content. All seven principles have focused practice; mock allocations await the October 7 instructor review.</p><p>Weeks 1–6: clinical reasoning and foundational integrity; both assigned ASHA assessment videos; standardized administration, scores and psychometrics; cultural-linguistic assessment; the complete evaluation and interview; oral mechanism and the assigned OPE video; sampling and calculations; observation, dynamic assessment, play and narratives; comprehensive SSD and GFTA recording; functional SSD versus CAS.</p><p>Textbook review stayed within Chapters 1, 2, 3, 6, 7 and relevant portions of 8/9. The September 23 lecture confirms the Week 5 narrative/semantic material. The former “not yet lectured” caveat has been removed from current teaching.</p>${window.DX_CHAPTERS.map(c=>`<p><strong>${esc(c.title)}:</strong> ${esc(c.source)}</p>`).join('')}</section><section class="card"><h2>Format and limits</h2><p>Both mock exams retain their existing questions, keys, allocations and saved runs. Only mastery practice has the October 6 question revisions; mock updates await the instructor review.</p><p><strong>Exam: Monday, October 12.</strong> Ethan reported the postponement on October 2. The formatting transcript and instructor study guide are expected Wednesday, October 7; current exact exam counts and weights remain pending those materials.</p><p>Professor DNA guides negative stems, neighboring distractors, precise T/F swaps, concise cases, matching and requested-component listings. Historical Language Disorders Test 2 supplies the 20 T/F × 2 + 20 MC × 3 practice design. The historical Final also used matching, listings and procedures.</p><p>Current Exam One section counts and weights remain unconfirmed until the format transcript arrives. Mock B’s 100-point allocation and the 50-minute timer are practice choices. These forms intentionally sample this lab’s practice bank; they are not unseen independent pools.</p><p>Source panels distinguish original supplied figures from course-backed study explanations. The course’s CI wording does not mean that calculating an interval improves the instrument’s intrinsic reliability. Use the named borrowing convention for age calculations; exact 70/130 band endpoints are left unkeyed.</p></section>`;}
  function casMedia(){const m=window.DX_CAS_MEDIA;return `<section class="lesson chapter-explainer" aria-label="Topic explainer"><article class="card"><p class="eyebrow">Narrated slide comparison</p><h2>${esc(m.title)}</h2><video id="cas-film" controls playsinline preload="metadata" poster="${m.poster}" aria-label="Narrated functional SSD and CAS comparison"><source src="${m.src}" type="video/mp4"><track kind="captions" src="${m.captions}" srclang="en" label="English" default></video><p class="small">Original Week 6 classification and CAS figures, with guided emphasis. Narration: AI Voice Generator · Clear. ${stamp(m.duration)} · English captions.</p><div class="row movie-stage">${m.stages.map((x,k)=>`<button class="btn" data-topic="stage" data-stage="${k}">${esc(x.title)}</button>`).join('')}<a href="${m.src}" download>Download video</a><a href="${m.transcriptSrc}">Read transcript</a></div><details class="source-box"><summary>Stage explanations and course sources</summary>${m.stages.map(x=>`<h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>`).join('')}<p>The broader CAS infographic is context; slide 17 defines the three consensus features. This is original study narration and guided source reading, not the professor's recording or a patient demonstration.</p>${evidenceHTML(['week6-s4','week6-s17','week6-s18','book-p225','book-p227'])}</details></article></section>`;}
  function casLearn(){return `${media()}${tabs('learn')}<section><h2>The distinction you need to make</h2><p class="muted">The September 30 lecture explicitly raised differentiating functional SSD and CAS. Use these current-course facts with the multiple-choice, true/false, matching, and listing formats from her last two Language Disorders exams.</p><div class="card tablewrap" role="region" aria-label="Functional SSD and CAS comparison" tabindex="0"><table class="topic-table"><thead><tr><th>Compare</th><th>Functional SSD profile</th><th>CAS concern</th></tr></thead><tbody><tr><td>Classification</td><td><mark class="study-term">No known physical cause</mark>; articulation or phonological difficulties</td><td>Organic disorder of speech <mark class="study-term">motor planning and sequencing</mark></td></tr><tr><td>Repeated productions</td><td><mark class="study-term">Relatively stable productions</mark> and predictable patterns</td><td><mark class="study-term">Inconsistent errors on repetitions</mark> of the same word or syllable</td></tr><tr><td>Joining sounds</td><td>Transitions do not supply the concerning CAS feature cluster</td><td><mark class="study-term">Lengthened or disrupted coarticulatory transitions</mark></td></tr><tr><td>Stress</td><td><mark class="study-term">Intact prosody</mark> supports the functional profile</td><td><mark class="study-term">Inappropriate lexical or phrasal stress</mark></td></tr><tr><td>Interpretation</td><td>Whole profile supports a functional explanation</td><td>The feature cluster supports <mark class="study-term">further motor speech assessment</mark></td></tr></tbody></table></div><div class="callout-cas"><p><strong>One feature is not a diagnosis.</strong> The profiles can overlap. A child with CAS can also have a phonological disorder.</p></div>${evidenceHTML(['week6-s4','week6-s17','book-p225'])}${window.DXSectionStudy.button('cas:profile','Functional SSD and CAS: interpret the whole profile')}</section><section><h2>Learn the three. Keep them distinct.</h2><div class="feature-list"><article class="feature"><span>1</span><h3>Inconsistent errors</h3><p>The same target changes across repetitions. Compare the same word, not unrelated words.</p></article><article class="feature"><span>2</span><h3>Disrupted transitions</h3><p>Sounds or syllables do not join smoothly. Joining and accuracy are separate observations.</p></article><article class="feature"><span>3</span><h3>Inappropriate prosody</h3><p>Listen for lexical or phrasal stress. Unusual stress belongs to prosody, not inconsistency.</p></article></div>${evidenceHTML(['week6-s17','week6-s18'])}${window.DXSectionStudy.button('cas:features','The three CAS features')}</section><section class="topic-grid" style="margin-top:24px"><article class="card"><h2>Choose the next evidence</h2><p>Formal articulation testing and connected speech describe productions. Oral mechanism and motor speech assessment help investigate the suspected mechanism. Dynamic assessment <mark class="study-term">compares responses to models, slower rate, simultaneous production, or tactile cues</mark>.</p>${evidenceHTML(['week6-s19','book-p227'])}${window.DXSectionStudy.button('cas:assessment','Choose the next evidence')}</article><article class="card"><h2>Check the linguistic system</h2><p>A difference from Mainstream American English <mark class="study-term">alone cannot establish SSD</mark>. Interpret the productions in the child’s languages or dialects. <mark class="study-term">Expected linguistic patterns</mark> explain a difference; <mark class="study-term">unexpected difficulties</mark> warrant investigation.</p>${evidenceHTML(['week6-s20'])}${window.DXSectionStudy.button('cas:language','Check the linguistic system')}</article></section><section class="card"><h2>Your exam wording</h2><label for="cas-note">Write the comparison in your own words.</label><textarea id="cas-note" data-topic-input="note" rows="4" placeholder="What would make you investigate CAS rather than stop at a functional explanation?">${esc(topic().note.value||'')}</textarea><p class="saved-text" id="note-status">${topic().note.at?'Saved in this browser.':'Notes save automatically.'}</p></section><div class="row lead-actions"><a class="btn primary" href="#/topic/practice/cas">Practice this topic</a><a class="btn" href="#/topic/cases/cas">Try the cases</a></div>`;}
  function media(){if(chapter.id==='cas')return casMedia();const original=window.DX_COURSE_MEDIA[chapter.id],m={...original,src:original.src+'?v=20261002-visuals',poster:original.poster+'?v=20261002-visuals'};return `<section class="lesson chapter-explainer"><article class="card"><p class="eyebrow">Narrated course-source walkthrough</p><h2>${esc(m.title)}</h2><video id="cas-film" controls playsinline preload="metadata" poster="${m.poster}"><source src="${m.src}" type="video/mp4"><track kind="captions" src="${m.captions}" srclang="en" label="English" default></video><p class="small">Source-faithful teaching diagrams and supplied course figures. AI Voice Generator · Clear · ${stamp(m.duration)} · English captions.</p><div class="row movie-stage">${m.stages.map((x,k)=>`<button class="btn" data-topic="stage" data-stage="${k}">${esc(x.title)}</button>`).join('')}<a href="${m.src}" download>Download video</a><a href="${m.transcriptSrc}">Read transcript</a></div><details class="source-box"><summary>Stage explanations and sources</summary>${m.stages.map(x=>`<h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>`).join('')}<p>${esc(chapter.source)}. Original educational narration; schematic process diagrams are not patient demonstrations.</p></details></article></section>`;}
  function learn(){const D=window.DXGuideDesign;if(chapter.id==='cas')return `<div class="cas-reading">${D.legend()}${casLearn()}</div>`;const modules=chapter.modules.map(id=>window.DX_COURSE_GUIDE.find(m=>m.id===id));return `${media()}${tabs('learn')}${D.legend()}${D.route(chapter,modules)}${modules.map((m,n)=>`<section class="guide-module">${D.moduleHead(m,n)}${m.sections.map((s,i)=>D.section(m,s,i)).join('')}</section>`).join('')}<section class="card"><h2>Your exam wording</h2><label for="cas-note">Write the distinctions in your own words.</label><textarea id="cas-note" data-topic-input="note" rows="4">${esc(Store.topic(api.state,'chapter-'+chapter.id).note.value||'')}</textarea><p id="note-status" class="saved-text">Notes save automatically in this browser.</p></section><div class="row"><a class="btn pri" href="#/topic/practice/${chapter.id}">Practice this chapter</a><a class="btn" href="#/topic/cases/${chapter.id}">Case decisions</a></div>`;}

  function activeRun(){const t=topic();return Object.values(t.runs).filter(r=>r.status==='active').sort((a,b)=>b.updated-a.updated)[0]||null;}
  function chapterConcepts(id){const seen=new Set();T.items.forEach(q=>{if(q.chapter===id&&q.type!=='list'&&T.concepts[q.concept])seen.add(q.concept);});return [...seen];}
  function conceptBadge(v){if(!v)return '<span class="pick-badge">Not started</span>';if(v.needsReview)return '<span class="pick-badge due">Review due</span>';if(v.mastered)return '<span class="pick-badge done">Mastered</span>';return v.attempts?`<span class="pick-badge learn">Learning ${v.correct}/${v.attempts}</span>`:'<span class="pick-badge">Not started</span>';}
  function builder(){const e=ev();const groups=window.DX_CHAPTERS.map((ch,n)=>{const cs=chapterConcepts(ch.id);if(!cs.length)return '';const mine=chapter&&chapter.id===ch.id;const mc=T.items.filter(q=>q.chapter===ch.id&&q.type==='mc').length;return `<details class="pick-group" ${mine?'open':''}><summary>${n+1}. ${esc(ch.title)} <span class="muted small">(${cs.length} concepts · ${mc} multiple choice · ${esc(ch.week)})</span></summary><label class="pick-all small"><input type="checkbox" data-topic="pick-all" data-chapter="${ch.id}" ${mine?'checked':''}> Select the whole chapter</label><div class="pick-grid">${cs.map(c=>`<label class="pick small"><input type="checkbox" class="pick-c" data-topic="pick" data-chapter="${ch.id}" value="${c}" ${mine?'checked':''}> <span>${esc(T.concepts[c])}</span> ${conceptBadge(e[c])}</label>`).join('')}</div></details>`;}).join('');
    return `<section class="card"><h2>Quick start</h2><div class="row"><button class="btn primary" data-topic="start" data-mode="practice">${chapter?'This chapter (adaptive, 25)':'Mixed (all chapters, 25)'}</button><button class="btn" data-topic="quick" data-quick="mc">Multiple choice only (20)</button><button class="btn" data-topic="start" data-mode="review">Targeted review</button><button class="btn" data-topic="start" data-mode="listing">Typed listing drill</button></div></section>
    <section class="card builder"><h2>Build your own</h2><div class="formrow"><label for="pick-n">Number of questions</label><select id="pick-n"><option>10</option><option selected>15</option><option>20</option><option>25</option><option>30</option><option value="999">All available</option></select></div><div class="formrow"><span>Question types</span><label><input type="checkbox" id="pick-mc" data-topic="pick"> Multiple choice only</label></div>${groups}<p class="muted small" id="pick-status" role="status"></p><div class="row"><button class="btn primary" data-topic="custom">Start with selected concepts</button><button class="btn" data-topic="pick-clear">Clear selection</button></div><p class="muted small">Multiple choice questions come first in every practice set. Missed questions return after two others.</p></section>`;}
  function pickStatus(){const el=document.getElementById('pick-status');if(!el)return;const cs=[...root.querySelectorAll('.pick-c:checked')].map(x=>x.value);const mcOnly=document.getElementById('pick-mc')?.checked;const n=T.items.filter(q=>q.type!=='list'&&cs.includes(q.concept)&&(!mcOnly||q.type==='mc')).length;el.textContent=cs.length?`${cs.length} concept${cs.length>1?'s':''} selected · ${n} question${n===1?'':'s'} available`:'No concepts selected yet.';root.querySelectorAll('[data-topic="pick-all"]').forEach(a=>{const kids=[...root.querySelectorAll(`.pick-c[data-chapter="${a.dataset.chapter}"]`)];const on=kids.filter(k=>k.checked).length;a.checked=on===kids.length&&on>0;a.indeterminate=on>0&&on<kids.length;});}
  function launchMenu(view){const r=activeRun(),qs=bank();let detail='';if(view==='cases')detail=`<h2>What does the evidence justify?</h2><p>Brief source-backed decisions connect observations with methods, interpretations and next steps.</p><button class="btn pri" data-topic="start" data-mode="cases">Start case decisions</button><button class="btn" data-topic="start" data-mode="boss">Cumulative 27-question drill</button>`;if(view==='test')detail=window.DX_COURSE_FORMS.map(f=>`<article><h2>${esc(f.title)}</h2><p>${esc(f.description)}</p><p>100 points · 50 minutes. Practice allocation; the current exam’s exact counts remain unconfirmed. Immediate feedback after each check, scored first responses preserved.</p><button class="btn pri" data-topic="start" data-mode="test" data-form="${f.id}">Start ${esc(f.title)}</button><a class="btn" href="#/topic/paper/${f.id}">Printable paper</a></article>`).join('<hr>');return `${tabs(view)}${r?`<section class="card"><h2>Saved activity</h2><p>${esc(labelRun(r))} · ${Object.keys(r.responses).length} checked</p><p class="muted small">Finish or end this activity before starting a new set; start buttons return you here until then.</p><div class="row"><a class="btn" href="#/topic/run/${r.id}">Resume</a><button class="btn" data-topic="end" data-run="${r.id}">End activity and retain history</button></div></section>`:''}${view==='practice'?builder():`<section class="card">${detail}</section><section class="card"><h2>Mastery comes from evidence</h2>${skills()}</section>`}`;}
  function start(type,concept,formId,opts){if(activeRun()&&!opts?.preserveActive){go('run/'+activeRun().id);return;}let qs=opts?T.items.filter(q=>q.type!=='list'&&(!opts.concepts||opts.concepts.includes(q.concept))&&(!opts.mcOnly||q.type==='mc')&&(!opts.items||opts.items.includes(q.id))):bank().filter(q=>q.type!=='list'&&(!concept||q.concept===concept));let form=null;if(type==='practice'||type==='review'){if(type==='review'){const e=ev();qs=qs.filter(q=>e[q.concept].needsReview);}qs=window.DXE.planSession(qs,{size:opts?.n||25,history:api.state.items}).map(o=>byId[o.id]);}if(type==='listing')qs=bank().filter(q=>q.type==='list');if(type==='cases')qs=E.shuffle(qs.filter(q=>q.case||(q.style||[]).includes('case'))).slice(0,15);if(type==='boss')qs=window.DX_CHAPTERS.flatMap(c=>E.shuffle(T.items.filter(q=>q.chapter===c.id&&q.type!=='list')).slice(0,3));if(type==='test'){form=window.DX_COURSE_FORMS.find(f=>f.id===formId)||window.DX_COURSE_FORMS[0];qs=form.items.map(x=>({...mockById[x.id],points:x.points}));}if(type!=='test'&&type!=='listing'){const mcFirst=qs.filter(q=>q.type==='mc');qs=mcFirst.concat(qs.filter(q=>q.type!=='mc'));}if(!qs.length){root.insertAdjacentHTML('beforeend','<p role="status">No questions due in this selection. Choose another chapter or mixed practice.</p>');return;}const run=E.makeRun(type,qs,Date.now(),id());run.chapter=chapter?.id||null;run.label=form?.title||opts?.label||(type==='boss'?'Cumulative drill':labels[type])+(chapter?' · '+chapter.title:'');if(type==='test'){run.formId=form.id;run.deadlineAt=Date.now()+50*60*1000;}change(t=>{t.runs[run.id]=run;t.activeId=run.id;});go('run/'+run.id);}
  function choiceHTML(q,view,a,reveal,name){return `<div class="topic-options" role="radiogroup" aria-label="${name==='correction'?'Correction choices':'Answer choices'}">${(q.type==='mc'?view:[true,false]).map((k,n)=>{const chosen=a.choice===k,key=k===q.answer,mark=reveal&&key?'answer-correct':reveal&&chosen&&!key?'answer-wrong':'';return `<label class="topic-option ${mark}"><input type="radio" name="${name}" data-topic-input="${name==='correction'?'correction':'choice'}" value="${k}" ${chosen?'checked':''} ${reveal?'disabled':''}><span class="letter">${String.fromCharCode(65+n)}</span><span>${esc(q.type==='mc'?q.options[k]:k?'True':'False')}${reveal&&key?`<span class="choice-result">${chosen?'Your answer · Correct':'Correct option'}</span>`:reveal&&chosen?'<span class="choice-result">Your answer · Incorrect</span>':''}</span></label>`;}).join('')}</div>`;}
  function answerHTML(q,o,a,reveal){if(q.type==='mc'||q.type==='tf')return choiceHTML(q,o.view,a,reveal,'answer');
    if(q.type==='list')return `<label for="listing-answer">Your answer, one point per line</label><textarea id="listing-answer" data-topic-input="listing" rows="5" ${reveal?'readonly':''} placeholder="Retrieve the list before revealing the rubric.">${esc(a.text||'')}</textarea>`;
    if(q.type==='num')return `<div class="numeric-fields">${q.fields.map((f,k)=>`<label>${esc(f.label)}<input inputmode="decimal" data-topic-input="num" data-field="${k}" value="${esc(a.vals?.[k]??'')}" ${reveal?'readonly':''} class="${reveal?(E.grade(q,a).parts?.[k]?'answer-correct':'answer-wrong'):''}"></label>`).join('')}</div>`;
    if(q.type==='multi')return `<div class="topic-options">${o.view.map(k=>`<label class="topic-option ${reveal&&q.answer.includes(k)?'answer-correct':reveal&&a.choices?.includes(k)?'answer-wrong':''}"><input type="checkbox" data-topic-input="multi" value="${k}" ${a.choices?.includes(k)?'checked':''} ${reveal?'disabled':''}><span>${esc(q.options[k])}</span></label>`).join('')}</div>`;
    if(q.type==='order')return `<p>Choose each stage’s position. Each position must be used once.</p>${o.view.map(k=>`<div class="topic-pair"><label for="topic-order-${k}">${esc(q.steps[k])}</label><select id="topic-order-${k}" data-topic-input="order" data-step="${k}" ${reveal?'disabled':''}><option value="">Choose position…</option>${q.steps.map((_,n)=>`<option value="${n}" ${a.seq?.[n]===k?'selected':''}>${n+1}${reveal&&n===k?' · correct':''}</option>`).join('')}</select></div>`).join('')}`;
    if(q.type==='sort')return o.view.map(k=>`<div class="topic-pair"><label for="topic-sort-${k}">${esc(q.items[k][0])}${reveal?`<span class="choice-result" style="color:var(--${a.map?.[k]===q.items[k][1]?'ok':'bad'})">Correct category: ${esc(q.items[k][1])}</span>`:''}</label><select id="topic-sort-${k}" data-topic-input="sort" data-item="${k}" ${reveal?'disabled':''}><option value="">Choose category…</option>${q.groups.map(b=>`<option value="${esc(b)}" ${a.map?.[k]===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div>`).join('');
    if(q.type==='hotspot')return window.DXV.render(q.visual,{mode:'hotspot',selected:a.zone,reveal:reveal?{answer:q.answer,chosen:a.zone}:null,view:o.view});
    return (o.rows||q.pairs.map((_,k)=>k)).map(k=>{const p=q.pairs[k];return `<div class="topic-pair"><label for="pair-${k}">${esc(p[0])}${reveal?`<span class="choice-result" style="color:var(--${a.map&&a.map[k]===k?'ok':'bad'})">${a.map&&a.map[k]===k?'Correct':'Correct match: '+esc(p[1])}</span>`:''}</label><select id="pair-${k}" data-topic-input="match" data-pair="${k}" ${reveal?'disabled':''}><option value="">Choose a feature…</option>${o.view.map(j=>`<option value="${j}" ${a.map&&a.map[k]===j?'selected':''}>${esc(q.pairs[j][1])}</option>`).join('')}</select></div>`;}).join('');
  }
  function feedback(q,o,r,v){const manual=q.type==='list',correct=q.type==='list'?'':q.type==='mc'?q.options[q.answer]:q.type==='tf'?q.answer?'True':'False':q.type==='match'?q.pairs.map(p=>p[1]).join('; '):q.type==='num'?q.fields.map(f=>f.label+': '+f.answer).join('; '):q.type==='multi'?q.answer.map(k=>q.options[k]).join('; '):q.type==='order'?q.steps.join(' → '):q.type==='sort'?q.items.map(x=>x.join(' → ')).join('; '):q.answer,ss=r.selfScores[o.key];return `<section class="topic-feedback" data-run-id="${r.id}" data-occurrence-id="${o.key}" aria-label="Checked answer feedback"><p class="verdict ${manual?'':v.correct?'ok':'no'}" role="status">${manual?'Rubric revealed · self-score each component':v.correct?'Correct':'Not quite'}</p>${manual?'':`<p class="correct-answer">Correct answer: ${esc(correct)}</p>`}<p>${esc(q.explain)}</p>${q.why&&!v.correct?`<p><strong>Your choice:</strong> ${esc(q.why[v.answer.choice]||'')}</p>`:''}${q.fix?`<p><strong>Source statement:</strong> ${esc(q.fix)}</p>`:''}<p class="muted small">First answer saved · ${esc(v.confidence)} confidence${v.assisted?' · source hint used':''}. ${v.requeue?`Returns after ${v.requeue} other questions.`:''}</p>${q.why?`<details class="distractors"><summary>Why each choice fits or fails</summary><ul>${q.options.map((x,k)=>`<li><strong>${esc(x)}:</strong> ${esc(q.why[k])}</li>`).join('')}</ul></details>`:''}${manual?`<div class="rubric"><p><strong>Mark only the components present in your first answer.</strong> Meaning counts; exact wording is not required.</p>${q.rubric.map((x,k)=>`<label><input type="checkbox" data-topic-input="rubric" data-rubric="${k}" ${ss&&ss.marks[k]?'checked':''}>${esc(x)}</label>`).join('')}<p class="saved-text">Self-score: ${ss?ss.marks.filter(Boolean).length:0}/${q.rubric.length}. ${ss?'Saved separately from your first answer.':'Confirm even a zero score.'}</p><button class="btn" data-topic="self-confirm">Confirm self-score</button></div>`:''}<p class="muted small">Question sources: ${(q.src||[]).map(x=>esc(x.s+' · '+x.loc)).join('; ')}</p>${evidenceHTML(q.evidence)}${(q.type==='mc'||q.type==='tf')?`<div class="correction">${correctionOpen===r.id+'/'+o.key?`${choiceHTML(q,o.view,{},false,'correction')}<div class="row" style="margin-top:12px"><button class="btn" data-topic="correct">Save correction</button><button class="btn" data-topic="correction-cancel">Cancel</button></div><p class="muted small">Corrections stay separate. The first answer above keeps its score and colors.</p>`:`<button class="btn" data-topic="correction-open">Make a correction</button>`}${r.corrections.filter(c=>c.key===o.key).map(c=>`<p class="muted small">Correction ${date(c.at)}: ${esc(q.type==='mc'?q.options[c.answer.choice]:c.answer.choice?'True':'False')} · ${c.correct?'correct':'needs review'}.</p>`).join('')}</div>`:''}</section>`;}
  function archivedDraft(q,a){if(q.type==='mc')return q.options[a.choice]||'No option selected';if(q.type==='tf')return typeof a.choice==='boolean'?(a.choice?'True':'False'):'No option selected';if(q.type==='multi')return (a.choices||[]).map(i=>q.options[i]).join('; ')||'No options selected';if(q.type==='num')return q.fields.map((f,i)=>f.label+': '+(a.vals?.[i]??'blank')+(f.unit?' '+f.unit:'')).join('; ');if(q.type==='match')return q.pairs.map((p,i)=>p[0]+': '+(q.pairs[a.map?.[i]]?.[1]||'blank')).join('; ');if(q.type==='order')return (a.seq||[]).map(i=>q.steps[i]||'blank').join(' → ');if(q.type==='sort')return q.items.map((v,i)=>v[0]+': '+(a.map?.[i]||'blank')).join('; ');if(q.type==='hotspot')return a.zone?'Selected figure region: '+a.zone:'No figure region selected';return a.text||'No draft response';}
  function scopeHistoryHTML(o){if(!o.scopeHistory?.length)return '';const h=o.scopeHistory.at(-1),d=h.draft;return `<details class="source-box scope-update"><summary>Question updated to the main idea${d?' · earlier draft retained':''}</summary><p>Unanswered video-detail recall was replaced with a course principle or a self-contained application. Checked answers keep their original questions and scores.</p>${d?`<h3>Earlier wording</h3><p>${esc(h.occurrence.snapshot.stem)}</p><p><strong>Earlier draft (unscored):</strong> ${esc(archivedDraft(h.occurrence.snapshot,d.answer||{}))}</p><p class="small">Earlier confidence: ${esc(d.confidence||'not selected')}. This unscored draft remains in your backup.</p>`:''}</details>`;}
  function runView(runId){const r=topic().runs[runId];if(!r)return `<p>That saved activity is unavailable.</p><a href="#/topic/practice">Return to practice</a>`;if(r.status!=='active')return results(r);
    const o=r.items[r.index],q=o.snapshot,v=r.responses[o.key],draft=r.drafts[o.key]||{answer:{},confidence:null},a=v?v.answer:draft.answer;
    return `${tabs(r.type==='test'?'test':r.type==='cases'?'cases':'practice')}<section class="topic-session"><p class="eyebrow">${r.type==='test'?(q.type==='tf'?'Part I · True / False':q.type==='mc'?'Part II · Multiple choice':q.type==='match'?'Part III · Matching':q.type==='num'?'Part V · Procedures':'Part IV · Listing'):''}</p><div class="qmeta"><span>${esc(labelRun(r))} · ${r.index+1}/${r.items.length}${o.rep?' · spaced return':''}</span>${r.deadlineAt?'<span id="topic-timer" role="timer"></span>':''}<span class="saved-text" id="run-save">${api.storageOK?'Saved in this browser':'Storage unavailable; export before closing'}</span></div><div class="mini-bar" aria-label="${r.index} of ${r.items.length} questions visited"><i style="width:${Math.round(r.index/r.items.length*100)}%"></i></div><article class="card qcard"><div class="qmeta"><span>${q.type==='mc'?'Multiple choice':q.type==='tf'?'True / False':q.type==='match'?'Matching':q.type==='num'?'Calculation':q.type==='hotspot'?'Figure identification':q.type==='order'?'Sequence':q.type==='multi'?'Select all':q.type==='sort'?'Classification':'Listing'} · Original practice</span><span>First response stays scored</span></div><h2 class="qstem">${esc(q.stem).replace(/\b(NOT|EXCEPT|LEAST|FALSE)\b/g,'<strong>$1</strong>')}</h2>${scopeHistoryHTML(o)}${answerHTML(q,o,a,!!v)}${!v?`<div class="topic-conf"><p id="confidence-label">How confident are you?</p><div class="row" role="group" aria-labelledby="confidence-label">${['low','medium','high'].map(c=>`<button class="btn ${draft.confidence===c?'on':''}" data-topic="confidence" data-confidence="${c}" aria-pressed="${draft.confidence===c}">${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div></div><div class="row" style="margin-top:20px"><button class="btn primary" id="topic-check" data-topic="check" ${E.answered(q,a)&&draft.confidence?'':'disabled'}>${q.type==='list'?'Reveal rubric':'Check answer'}</button><button class="btn" data-topic="hint">Open a source hint</button></div>${draft.assisted?`<p class="muted small">Source hint used; this attempt will not earn mastery.</p>${evidenceHTML(q.evidence)}`:''}`:feedback(q,o,r,v)}<div class="row" style="margin-top:22px">${r.index?'<button class="btn" data-topic="previous">Previous</button>':''}${v?`<button class="btn primary" data-topic="next" ${q.type==='list'&&!r.selfScores[o.key]?'disabled':''}>${r.index===r.items.length-1?'Finish activity':'Next question'}</button>`:''}<button class="btn" data-topic="end" data-run="${r.id}">End activity</button></div><p id="topic-message" class="topic-error small" role="status"></p></article>${r.type==='test'?`<nav class="qnav" aria-label="Test questions">${r.items.map((x,k)=>`<button class="btn ${r.responses[x.key]?'checked':''} ${k===r.index?'current':''}" data-topic="jump" data-index="${k}" aria-label="Question ${k+1}${r.responses[x.key]?', checked':''}">${k+1}</button>`).join('')}</nav>`:''}</section>`;
  }
  function end(runId){change(t=>{const r=t.runs[runId];if(!r||r.status!=='active')return;r.status=r.items.every(o=>r.responses[o.key])?'completed':'ended';r.endedAt=Date.now();r.updated=Date.now();if(t.activeId===runId)t.activeId=null;});go('results/'+runId);}
  function results(r){const sc=E.score(r),old=r.items.some(o=>o.snapshot.version!==T.revision);return `${old?'<div class="callout">Saved content version retained. These questions and their original point values are preserved from the activity you started.</div>':''}${tabs(r.type==='test'?'test':'practice')}<h2>${esc(labelRun(r))} · ${r.status==='completed'?'Complete':'Ended'}</h2><p class="muted">First answers are retained. Unanswered questions remain neutral. ${sc.pending?'A listing still needs your self-score.':''}</p><div class="run-scores"><div><strong>${sc.points}/${sc.max}</strong><span>${r.type==='test'?'Exam practice points':'Weighted practice points'}${sc.pending?' · provisional':''}</span></div><div><strong>${sc.answered}/${sc.total}</strong><span>first questions checked</span></div><div><strong>${r.corrections.length}</strong><span>separate corrections</span></div></div><div class="card"><h2>Review the saved questions</h2>${r.items.filter(o=>!o.rep).map((o,k)=>{const v=r.responses[o.key];return `<details class="source-box" ${reviewOpen.has(r.id+'/'+o.key)||correctionOpen===r.id+'/'+o.key?'open':''}><summary>Question ${k+1} · ${v?o.snapshot.type==='list'?'Self-scored listing':v.correct?'Correct':'Needs review':'Unanswered'}</summary><h3>${esc(o.snapshot.stem)}</h3>${v?answerHTML(o.snapshot,o,v.answer,true)+feedback(o.snapshot,o,r,v):'<p class="muted">No first response was checked. This item supplies no mastery evidence.</p>'}</details>`;}).join('')}</div><div class="row"><a class="btn primary" href="#/topic/practice">Return to practice</a><a class="btn" href="#/topic/progress">View saved progress</a></div>`;}
  function progress(){const runs=Object.values(topic().runs).sort((a,b)=>b.startedAt-a.startedAt);return `${tabs('progress')}<section class="card"><h2>Your course skills</h2><p class="mastery-rule"><strong>Two different questions, two consecutive correct answers.</strong> Both must be unhinted; the second needs medium or high confidence. A miss resets the qualifying streak and adds review. Previously earned mastery is retained. Corrections and self-scored writing remain in your history without awarding automatic mastery.</p>${skills(T.completionConceptIds)}<h2>New activity and checklist skills</h2><p class="small">These eight additions share your saved mastery record and have separate completion totals. Your original chapter percentages keep their original totals.</p>${skills(T.addedCompletionIds)}<p class="muted small">Mastery is retained after a later miss; review is tracked alongside it. Listings and corrections remain separate from mastery.</p></section><section class="card"><h2>Saved activities</h2>${runs.length?runs.map(r=>{const sc=E.score(r);return `<div class="history-row"><div><p><strong>${esc(labelRun(r))}</strong> · ${esc(r.status)}</p><small class="muted">${date(r.startedAt)} · ${sc.answered}/${sc.total} checked · ${sc.points}/${sc.max} points${sc.pending?' · listing score pending':''}</small></div><a class="btn" href="#/topic/${r.status==='active'?'run':'results'}/${r.id}">${r.status==='active'?'Resume':'Review'}</a></div>`;}).join(''):'<p class="muted">No activities yet.</p>'}</section><details class="source-box"><summary>Scope and evidence</summary><p>All nine Exam One chapters, source-backed practice and typed listings. Current lecture and deck control content. Historical COMD 4382 Test 2 and Final control format: concise neighboring choices, negative stems, true/false swaps, matching, and requested-component listings.</p><p>Professor DNA revision: ${esc(T.dna)}.</p><p>Source review: <a href="docs/EXAM1_RELEASE.md" target="_blank">Release and source review</a>. Content revision: ${esc(T.revision)}. Storage identity: comd4756-lab-v2.</p></details>`;}
  function backupPage(){return `<section class="card"><h2>Keep a backup</h2><p>Export includes your existing Diagnostics progress and this topic’s drafts, first answers, confidence, saved question versions, corrections, notes, and activities. Import merges records and creates a recoverable backup first.</p><div class="row"><button class="btn primary" data-topic="export">Export Diagnostics progress</button><label class="btn">Import & merge<input id="topic-import" type="file" accept="application/json,.json" hidden></label><a class="btn" href="#/progress">Existing lab progress</a></div><p class="saved-text" id="backup-message" role="status">${api.storageOK?'Storage is working.':'Browser storage is unavailable; export before closing.'}</p><p class="muted small">Backups stay on your device. Localhost and the shared GitHub site have separate browser storage. Use the same browser/profile and hosted URL to retain hosted progress.</p></section>`;}
  function paper(){const f=window.DX_COURSE_FORMS.find(f=>f.id===location.hash.split('/')[3])||window.DX_COURSE_FORMS[0];return `<section class="card"><h2>${esc(f.title)} · 100 points</h2><p>${esc(f.description)}</p><p>Name: __________________ Date: __________ Score: ______ / 100</p><button class="btn" data-topic="print">Print / Save PDF</button></section>${f.items.map((x,n)=>{const q=mockById[x.id];return `<article class="card paper-question"><h3>${n+1}. ${esc(q.stem)} (${x.points} points)</h3>${q.type==='tf'?'<p>True / False</p>':q.type==='mc'?`<ol type="A">${E.shuffle(q.options).map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:q.type==='match'?`<p>Terms: ${E.shuffle(q.pairs.map(p=>p[1])).map(esc).join(' · ')}</p>${q.pairs.map(p=>`<p>_____ ${esc(p[0])}</p>`).join('')}`:q.type==='num'?q.fields.map(field=>`<p>${esc(field.label)}: __________________</p>`).join(''):q.rubric.map(()=>'<p>__________________________________________________</p>').join('')}</article>`;}).join('')}`;}
  function current(){const p=location.hash.split('/'),rid=p[3],r=topic().runs[rid];if(!r||r.status!=='active')return null;return {r,o:r.items[r.index],draft:r.drafts[r.items[r.index].key]||{answer:{},confidence:null}};}
  function feedbackContext(el){const box=el.closest('[data-run-id]');if(!box)return null;const r=topic().runs[box.dataset.runId],o=r&&r.items.find(x=>x.key===box.dataset.occurrenceId);return r&&o?{r,o}:null;}
  function saveDraft(fn){const c=current();if(!c||c.r.responses[c.o.key])return;change(t=>{const r=t.runs[c.r.id],d=r.drafts[c.o.key]||{answer:{},confidence:null};fn(d);d.scopeVersion=c.o.snapshot.version;d.at=Date.now();r.drafts[c.o.key]=d;r.updated=Date.now();});const n=current(),b=document.getElementById('topic-check');if(b&&n)b.disabled=!(E.answered(n.o.snapshot,n.draft.answer)&&n.draft.confidence);const status=document.getElementById('run-save');if(status)status.textContent=api.storageOK?'Draft saved':'Storage unavailable; export before closing';}
  function check(){const c=current();if(!c)return;const q=c.o.snapshot;if(!E.answered(q,c.draft.answer)||!c.draft.confidence)return;change(t=>{const r=t.runs[c.r.id];if(r.responses[c.o.key])return;const d=r.drafts[c.o.key],g=E.grade(q,d.answer),v={answer:Store.clone(d.answer),confidence:d.confidence,correct:g.ok,checkedAt:Date.now(),assisted:!!d.assisted,version:q.version};r.responses[c.o.key]=v;v.requeue=E.requeue(r,c.o,v);r.updated=Date.now();});renderNow();document.querySelector('.topic-feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
  function bind(view){
    if(view==='learn'){document.querySelectorAll('[data-guide-jump]').forEach(b=>b.addEventListener('click',()=>{const target=document.getElementById(b.dataset.guideJump);target?.scrollIntoView({block:'start',behavior:'auto'});target?.focus({preventScroll:true});}));const v=document.getElementById('cas-film');v?.addEventListener('timeupdate',()=>{const stages=(chapter.id==='cas'?window.DX_CAS_MEDIA:window.DX_COURSE_MEDIA[chapter.id]).stages;let k=0;stages.forEach((s,n)=>{if(v.currentTime>=s.start)k=n;});document.querySelectorAll('[data-topic="stage"]').forEach(b=>b.classList.toggle('active',Number(b.dataset.stage)===k));});}
    const c=current();if(c&&c.r.deadlineAt){const update=()=>{const left=Math.max(0,Math.ceil((c.r.deadlineAt-Date.now())/1000));const el=document.getElementById('topic-timer');if(el)el.textContent=stamp(left)+' remaining';if(!left){clearInterval(tick);end(c.r.id);}};update();if(topic().runs[c.r.id]?.status==='active')tick=setInterval(update,1000);}
  }
  function render(a,parts){api=a;root=a.app;clearInterval(tick);const view=parts[0]||'home';chapter=view==='activity'?chapterById.reasoning:chapterById[parts[1]]||(view==='learn'?chapterById.cas:null);if(['run','results'].includes(view))chapter=chapterById[topic().runs[parts[1]]?.chapter]||null;const navView=['run','results'].includes(view)?topic().runs[parts[1]]?.type==='test'?'test':'practice':['learn','activity'].includes(view)?'guide':view;document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.r==='topic/'+navView));const content=view==='activity'?window.DXOct5.page(Store.topic(api.state,'chapter-reasoning').note):view==='home'?home():view==='guide'?guide():view==='learn'?learn():view==='review'?review():view==='sources'?sourcePage():view==='backup'?backupPage():view==='paper'?paper():['practice','cases','test'].includes(view)?launchMenu(view):view==='run'?runView(parts[1]):view==='results'?topic().runs[parts[1]]?results(topic().runs[parts[1]]):'<p>Activity unavailable.</p>':progress();root.innerHTML=`<div class="topic-shell">${header(view)}${content}</div>`;bind(view);if(view==='practice')pickStatus();}
  document.addEventListener('input',e=>{const el=e.target;if(!root?.contains(el))return;const kind=el.dataset.topicInput;if(kind==='note'){api.mutate(s=>{Store.topic(s,chapter.id==='cas'?'cas':'chapter-'+chapter.id).note={value:el.value,at:Date.now()};});document.getElementById('note-status').textContent=api.storageOK?'Saved in this browser.':'Storage unavailable; export before closing.';}
    if(kind==='listing')saveDraft(d=>d.answer.text=el.value);if(kind==='num')saveDraft(d=>{d.answer.vals=d.answer.vals||[];d.answer.vals[el.dataset.field]=el.value;});
  });
  document.addEventListener('change',async e=>{const el=e.target;if(!root?.contains(el))return;const kind=el.dataset.topicInput;
    if(kind==='multi')saveDraft(d=>{const a=new Set(d.answer.choices||[]);el.checked?a.add(Number(el.value)):a.delete(Number(el.value));d.answer.choices=[...a];});if(kind==='sort')saveDraft(d=>{d.answer.map=d.answer.map||{};d.answer.map[el.dataset.item]=el.value;});if(kind==='order')saveDraft(d=>{const c=current(),seq=(d.answer.seq||Array(c.o.snapshot.steps.length).fill(null)).slice();const step=Number(el.dataset.step),old=seq.indexOf(step);if(old>=0)seq[old]=null;if(el.value!=='')seq[Number(el.value)]=step;d.answer.seq=seq;});if(kind==='order')renderNow();
    if(kind==='choice'){const c=current();saveDraft(d=>d.answer.choice=c.o.snapshot.type==='tf'?el.value==='true':Number(el.value));}
    if(kind==='match')saveDraft(d=>{d.answer.map=d.answer.map||{};if(el.value==='')delete d.answer.map[el.dataset.pair];else d.answer.map[el.dataset.pair]=Number(el.value);});
    if(kind==='rubric'){const c=current()||feedbackContext(el);if(c)change(t=>{const r=t.runs[c.r.id],ss=r.selfScores[c.o.key]||{marks:c.o.snapshot.rubric.map(()=>false)};ss.marks[el.dataset.rubric]=el.checked;ss.at=Date.now();r.selfScores[c.o.key]=ss;r.updated=Date.now();});const b=root.querySelector('[data-topic="next"]');if(b)b.disabled=false;const text=el.closest('.rubric').querySelector('.saved-text');if(c&&text){const ss=topic().runs[c.r.id].selfScores[c.o.key];text.textContent='Self-score: '+ss.marks.filter(Boolean).length+'/'+ss.marks.length+'. Saved separately from your first answer.';}}
    if(el.id==='topic-import'){const msg=document.getElementById('backup-message');try{const file=el.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('Choose a Diagnostics backup under 8 MB.');const b=JSON.parse(await file.text());if(b.schema!=='comd4756-lab-v2-backup'||b.state?.schema!=='comd4756-lab-v2')throw Error('This file is not a Diagnostics backup.');api.importMerge(b.state);msg.textContent='Merged. Existing records and first responses preserved; a recovery backup was saved.';}catch(err){msg.textContent=err.message;}el.value='';}
  });
  document.addEventListener('click',e=>{const b=e.target.closest('[data-topic]');if(!b||!root?.contains(b))return;const act=b.dataset.topic,c=current()||feedbackContext(b);
    if(act==='stage'){const v=document.getElementById('cas-film');v.currentTime=(chapter.id==='cas'?window.DX_CAS_MEDIA:window.DX_COURSE_MEDIA[chapter.id]).stages[Number(b.dataset.stage)].start;v.play().catch(()=>{});}
    if(act==='oct5-jump'){e.preventDefault();document.getElementById(b.dataset.oct5Target)?.scrollIntoView({block:'start',behavior:'smooth'});}
    if(act==='start')start(b.dataset.mode,b.dataset.concept,b.dataset.form);
    if(act==='section-study'){const selection=window.DXSectionStudy.selection(b.dataset.section);if(selection?.items.length)start('practice',null,null,{...selection,preserveActive:true,label:'Section practice · '+b.dataset.sectionTitle});}
    if(act==='quick')start('practice',null,null,{mcOnly:true,n:20,concepts:chapter?chapterConcepts(chapter.id):null,label:'Multiple choice only'+(chapter?' · '+chapter.title:'')});
    if(act==='pick-all'){root.querySelectorAll(`.pick-c[data-chapter="${b.dataset.chapter}"]`).forEach(x=>x.checked=b.checked);pickStatus();}
    if(act==='pick')pickStatus();
    if(act==='pick-clear'){root.querySelectorAll('.pick-c').forEach(x=>x.checked=false);pickStatus();}
    if(act==='custom'){const cs=[...root.querySelectorAll('.pick-c:checked')].map(x=>x.value);const st=document.getElementById('pick-status');if(!cs.length){if(st)st.textContent='Pick at least one concept or chapter.';return;}const mcOnly=document.getElementById('pick-mc').checked;start('practice',null,null,{concepts:cs,mcOnly,n:Number(document.getElementById('pick-n').value),label:(mcOnly?'Custom multiple choice':'Custom practice')+' · '+cs.length+' concept'+(cs.length>1?'s':'')});}
    if(act==='end')end(b.dataset.run);
    if(act==='export')api.exportProgress();
    if(act==='print')window.print();
    if(!c)return;
    if(act==='confidence'){saveDraft(d=>d.confidence=b.dataset.confidence);root.querySelectorAll('[data-topic="confidence"]').forEach(x=>{const on=x===b;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on);});}
    if(act==='hint'){saveDraft(d=>{d.assisted=true;d.confidence='low';});renderNow();root.querySelector('.source-box')?.setAttribute('open','');}
    if(act==='check')check();
    if(act==='next'||act==='previous'||act==='jump'){if(act==='next'&&c.r.index===c.r.items.length-1){end(c.r.id);return;}change(t=>{const r=t.runs[c.r.id];r.index=act==='jump'?Number(b.dataset.index):Math.max(0,r.index+(act==='next'?1:-1));r.updated=Date.now();});correctionOpen=null;renderNow();document.querySelector('.qcard')?.scrollIntoView({block:'start'});}
    if(act==='self-confirm'){reviewOpen.add(c.r.id+'/'+c.o.key);change(t=>{const r=t.runs[c.r.id];r.selfScores[c.o.key]=r.selfScores[c.o.key]||{marks:c.o.snapshot.rubric.map(()=>false),at:Date.now()};r.updated=Date.now();});renderNow();}
    if(act==='correction-open'){correctionOpen=c.r.id+'/'+c.o.key;reviewOpen.add(c.r.id+'/'+c.o.key);renderNow();}
    if(act==='correction-cancel'){correctionOpen=null;renderNow();}
    if(act==='correct'){const selected=b.closest('.topic-feedback').querySelector('[data-topic-input="correction"]:checked');if(!selected){let msg=document.getElementById('topic-message')||b.closest('.correction').querySelector('[role=status]');if(!msg){msg=document.createElement('p');msg.className='topic-error small';msg.setAttribute('role','status');b.closest('.correction').append(msg);}msg.textContent='Choose a correction first.';return;}const q=c.o.snapshot,a={choice:q.type==='tf'?selected.value==='true':Number(selected.value)};change(t=>{const r=t.runs[c.r.id];r.corrections.push({id:id(),key:c.o.key,answer:a,correct:E.grade(q,a).ok,at:Date.now(),firstResponseAt:r.responses[c.o.key].checkedAt});r.updated=Date.now();});correctionOpen=null;renderNow();}
  });
  function hotspot(e){const z=e.target.closest('[data-zone]');if(!z||!root?.contains(z)||!current()||current().o.snapshot.type!=='hotspot')return;saveDraft(d=>d.answer.zone=z.dataset.zone);renderNow();}
  document.addEventListener('click',hotspot);document.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){if(e.target.closest('[data-zone]')){e.preventDefault();hotspot(e);}}});
  window.DXTopic={render,derive};
})();
